    const MODULE_ACTIONS = Object.freeze({
        light_manager: 'lightflow_section_lightflow_scene', shader_architect: 'sa_open_studio',
        lightflow_environment: 'lightflow_environment_composer', lightflow_atmosphere: 'lightflow_atmosphere_settings',
        studio_render: 'studio_render_export', lightflow_scene_links: 'lightflow_scene_link_add', lightflow_cinematic: 'lightflow_cinematic_open',
        visual_shader_graph: 'open_visual_shader_graph', bedrock_structure_studio: 'bedrock_structure_settings',
        lightflow_ui_diagnostics: 'open_lightflow_ui_diagnostics'
    });

    let openAction = null;
    let stylesheet = null;
    let hubDialog = null;
    let manifestState = makeEmbeddedManifest();
    let currentRef = 'main';
    let manifestOrigin = 'embedded';
    let operationLock = Promise.resolve();
    let disposed = false;
    let manifestEpoch = 0;
    let automaticTimer = null;
    let hubUpdateTimer = null;
    let updateNotification = null;
    let notificationHost = null;
    const requestControllers = new Set();
    let lastCheckTime = 0;




    function language() {
        const value = String(globalThis.Language?.code || globalThis.settings?.language?.value || navigator?.language || 'en').toLowerCase();
        return value.startsWith('es') ? 'es' : 'en';
    }

    function tr(key, values) {
        let value = TEXT[language()][key] || TEXT.en[key] || key;
        Object.entries(values || {}).forEach(([name, replacement]) => {
            value = value.replaceAll(`{${name}}`, String(replacement));
        });
        return value;
    }

    function makeEmbeddedManifest() {
        return {
            schema_version: 1,
            suite: 'Lightflow',
            repository: {...REPOSITORY},
            hub: {id: HUB_ID, file: 'lightflow_hub.js', version: HUB_VERSION, min_blockbench: '4.9.0'},
            modules: FALLBACK_MODULES.map(module => ({
                ...module,
                description: language() === 'es' ? module.description_es : module.description,
                dependencies: [...module.dependencies]
            }))
        };
    }

    function readJsonStorage(key, fallback) {
        try {
            const parsed = JSON.parse(localStorage.getItem(key) || 'null');
            return parsed && typeof parsed === 'object' ? parsed : fallback;
        } catch (_) {
            return fallback;
        }
    }

    function loadPreferences() {
        const stored = readJsonStorage(STORAGE_KEY, {});
        const preferences = {...DEFAULT_PREFERENCES, ...stored};
        if (!['stable', 'main', 'experimental'].includes(preferences.channel)) preferences.channel = 'stable';
        if (!['github', 'local'].includes(preferences.source)) preferences.source = 'github';
        preferences.experimentalBranch = sanitizeRef(preferences.experimentalBranch) || 'experimental';
        preferences.releaseTag = sanitizeRef(preferences.releaseTag);
        preferences.localDirectory = String(preferences.localDirectory || '');
        preferences.automaticChecks = preferences.automaticChecks !== false;
        preferences.lastAutomaticCheck = Math.max(0, Math.min(Date.now(), Number(preferences.lastAutomaticCheck) || 0));
        return preferences;
    }

    function savePreferences(preferences) {
        const safe = {
            channel: preferences.channel,
            releaseTag: sanitizeRef(preferences.releaseTag),
            experimentalBranch: sanitizeRef(preferences.experimentalBranch) || 'experimental',
            source: preferences.source,
            localDirectory: String(preferences.localDirectory || ''),
            automaticChecks: preferences.automaticChecks !== false,
            lastAutomaticCheck: Number(preferences.lastAutomaticCheck) || 0
        };
        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(safe)); } catch (_) { /* Session remains usable without storage. */ }
        return safe;
    }

    function sanitizeRef(value) {
        const ref = String(value || '').trim();
        return /^[A-Za-z0-9._/-]{1,120}$/.test(ref) && !ref.includes('..') && !ref.startsWith('/') && !ref.endsWith('/') ? ref : '';
    }

    function sanitizeFile(value) {
        const file = String(value || '').replace(/\\/g, '/').trim();
        return /^[A-Za-z0-9._/-]+\.js$/.test(file) && !file.includes('..') && !file.startsWith('/') ? file : '';
    }

    // Blockbench's native loadFromURL/loadFromFile derives the plugin ID from
    // the final filename before executing Plugin.register(). A valid bundle
    // must therefore be named <id>.js even when it lives in dist/.
    function assertPluginSourceFilename(id, source) {
        const cleanPath = String(source || '').split(/[?#]/, 1)[0].replace(/\\/g, '/');
        const filename = cleanPath.split('/').pop() || '';
        if (filename !== `${id}.js`) {
            throw new Error(`Plugin ${id} requires the filename ${id}.js; received ${filename || '(empty)'}. Use the canonical plugin file (bundled plugins may be stored in dist/).`);
        }
        return source;
    }

    function sanitizeImagePath(value) {
        const path = String(value || '').trim();
        return /^[A-Za-z0-9_/-]+\.(?:png|jpe?g|webp)$/i.test(path) && !path.startsWith('/') && !path.includes('..') ? path : '';
    }

    function imageUrl(path) {
        if (!sanitizeImagePath(path)) return '';
        if (manifestOrigin === 'local') {
            const desktop = desktopModules();
            if (!desktop) return '';
            try {
                const bytes = desktop.fs.readFileSync(desktop.path.join(currentRef, path));
                if (bytes.length > 4 * 1024 * 1024) return '';
                const type = /\.webp$/i.test(path) ? 'webp' : /\.jpe?g$/i.test(path) ? 'jpeg' : 'png';
                return `data:image/${type};base64,${bytes.toString('base64')}`;
            } catch (_) { return ''; }
        }
        return `https://raw.githubusercontent.com/${REPOSITORY.owner}/${REPOSITORY.name}/${currentRef.split('/').map(encodeURIComponent).join('/')}/${path.split('/').map(encodeURIComponent).join('/')}`;
    }

    function validatePluginSource(source, moduleId) {
        const escaped = moduleId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        // Compilation checks syntax without executing downloaded code.
        const literal = new RegExp(`(?:root\\.)?Plugin\\.register\\s*\\(\\s*['\"]${escaped}['\"]`);
        const constant = new RegExp(`(?:const|let|var)\\s+(\\w+)\\s*=\\s*['\"]${escaped}['\"]`);
        const match = String(source).match(constant);
        if (source.length < 80 || !(literal.test(source) || (match && new RegExp(`Plugin\\.register\\s*\\(\\s*${match[1]}\\s*,`).test(source)))) {
            throw new Error(tr('invalidSource', {name: moduleId}));
        }
        try { new Function(source); } catch (error) { throw new Error(`${moduleId}: ${error.message}`); }
        return source;
    }

    function normalizeVersion(value) {
        const match = String(value || '0.0.0').trim().match(/^(?:v)?(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:-([0-9A-Za-z.-]+))?/);
        if (!match) return {numbers: [0, 0, 0], prerelease: ''};
        return {numbers: [Number(match[1]), Number(match[2] || 0), Number(match[3] || 0)], prerelease: match[4] || ''};
    }

    function compareVersions(left, right) {
        const a = normalizeVersion(left);
        const b = normalizeVersion(right);
        for (let index = 0; index < 3; index++) {
            if (a.numbers[index] !== b.numbers[index]) return a.numbers[index] > b.numbers[index] ? 1 : -1;
        }
        if (a.prerelease === b.prerelease) return 0;
        if (!a.prerelease) return 1;
        if (!b.prerelease) return -1;
        return a.prerelease.localeCompare(b.prerelease, undefined, {numeric: true});
    }

    function sanitizeModule(raw) {
        if (!raw || typeof raw !== 'object') return null;
        const id = String(raw.id || '').trim();
        const file = sanitizeFile(raw.file);
        const filename = file ? file.split('/').pop() : '';
        // Bedrock Studio bundles its optional reference-model readers into one
        // self-contained script for URL installation. Keep every other module's
        // canonical filename validation intact.
        const validFilename = filename === `${id}.js`;
        if (!/^[a-z][a-z0-9_]{1,63}$/.test(id) || !file || !validFilename) return null;
        const dependencies = Array.isArray(raw.dependencies)
            ? [...new Set(raw.dependencies.map(String).filter(value => /^[a-z][a-z0-9_]{1,63}$/.test(value) && value !== id))]
            : [];
        const descriptionEn = String(raw.description_en || raw.description || '').slice(0, 320);
        const descriptionEs = String(raw.description_es || raw.description || '').slice(0, 320);
        return {
            id, file,
            title: String(raw.title || id).slice(0, 80),
            description: language() === 'es' ? descriptionEs : descriptionEn,
            description_en: descriptionEn,
            description_es: descriptionEs,
            version: String(raw.version || '0.0.0').slice(0, 32),
            min_blockbench: String(raw.min_blockbench || '4.9.0').slice(0, 24),
            variant: raw.variant === 'desktop' ? 'desktop' : 'both',
            icon: String(raw.icon || 'extension').slice(0, 64),
            icon_image: sanitizeImagePath(raw.icon_image),
            image: sanitizeImagePath(raw.image),
            group: VALID_GROUPS.has(raw.group) ? raw.group : 'specialized',
            recommended: raw.recommended === true,
            maturity: ['stable', 'beta', 'experimental', 'developer'].includes(raw.maturity) ? raw.maturity : 'stable',
            dependencies
        };
    }

    function sanitizeManifest(raw) {
        if (!raw || Number(raw.schema_version) !== 1 || !Array.isArray(raw.modules)) throw new Error('Unsupported Lightflow manifest');
        const modules = raw.modules.map(sanitizeModule).filter(Boolean);
        if (!modules.length || new Set(modules.map(module => module.id)).size !== modules.length) throw new Error('Invalid Lightflow module catalog');
        const ids = new Set(modules.map(module => module.id));
        modules.forEach(module => {
            if (module.dependencies.some(id => !ids.has(id))) throw new Error(`Missing dependency: ${module.id}`);
        });
        dependencyOrder(modules, modules.map(module => module.id));
        const rawHub = raw.hub || {};
        return {
            schema_version: 1,
            suite: String(raw.suite || 'Lightflow').slice(0, 64),
            repository: {...REPOSITORY},
            artwork: sanitizeImagePath(raw.artwork),
            hub: {
                id: HUB_ID,
                file: sanitizeFile(rawHub.file) || 'lightflow_hub.js',
                version: String(rawHub.version || HUB_VERSION).slice(0, 32),
                min_blockbench: String(rawHub.min_blockbench || '4.9.0').slice(0, 24)
            },
            modules
        };
    }

    async function fetchJson(url, timeout = 12000) {
        const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
        if (controller) requestControllers.add(controller);
        const timer = controller ? setTimeout(() => controller.abort(), timeout) : null;
        try {
            const response = await fetch(url, {cache: 'no-store', signal: controller?.signal, headers: {Accept: 'application/vnd.github+json, application/json'}});
            if (!response.ok) {
                const error = new Error(`HTTP ${response.status}`);
                error.releaseListRateLimited = url.startsWith('https://api.github.com/')
                    && (response.status === 429 || (response.status === 403
                        && (response.headers?.get('x-ratelimit-remaining') === '0' || !!response.headers?.get('retry-after'))));
                throw error;
            }
            return await response.json();
        } finally {
            requestControllers.delete(controller);
            if (timer) clearTimeout(timer);
        }
    }

    async function fetchText(url, timeout = 16000) {
        const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
        if (controller) requestControllers.add(controller);
        const timer = controller ? setTimeout(() => controller.abort(), timeout) : null;
        try {
            const response = await fetch(url, {cache: 'no-store', signal: controller?.signal});
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            return await response.text();
        } finally {
            requestControllers.delete(controller);
            if (timer) clearTimeout(timer);
        }
    }

    async function probeRemotePlugin(url, moduleId) {
        const source = await fetchText(url);
        return validatePluginSource(source, moduleId);
    }

    function rawUrl(ref, file) {
        const safeRef = sanitizeRef(ref);
        const safeFile = file === MANIFEST_FILE ? MANIFEST_FILE : sanitizeFile(file);
        if (!safeRef || !safeFile) throw new Error('Invalid Lightflow source reference');
        return `https://raw.githubusercontent.com/${REPOSITORY.owner}/${REPOSITORY.name}/${safeRef.split('/').map(encodeURIComponent).join('/')}/${safeFile.split('/').map(encodeURIComponent).join('/')}`;
    }

    function stableReleaseCandidates(releases) {
        if (!Array.isArray(releases)) return [];
        const candidates = releases.filter(release => release && !release.draft && !release.prerelease && sanitizeRef(release.tag_name));
        // A later Hub-only maintenance release must not downgrade the suite.
        // Explicit release selection remains untouched in fetchStableManifest.
        const suiteVersion = release => /^v(\d+)\.(\d+)\.(\d+)$/.exec(release.tag_name);
        return candidates.sort((a, b) => {
            const av = suiteVersion(a), bv = suiteVersion(b);
            if (!!av !== !!bv) return av ? -1 : 1;
            if (!av) return 0;
            for (let index = 1; index <= 3; index++) {
                const delta = Number(bv[index]) - Number(av[index]);
                if (delta) return delta;
            }
            return 0;
        });
    }

    async function fetchPublishedReleases() {
        const releases = [];
        for (let page = 1; ; page++) {
            const batch = await fetchJson(`https://api.github.com/repos/${REPOSITORY.owner}/${REPOSITORY.name}/releases?per_page=100&page=${page}`);
            if (!Array.isArray(batch)) throw new Error('Invalid GitHub releases response');
            for (const release of batch) {
                const tag = sanitizeRef(release?.tag_name);
                if (!tag || release.draft || releases.some(item => item.tag_name === tag)) continue;
                const published = typeof release.published_at === 'string' && Number.isFinite(Date.parse(release.published_at)) ? new Date(release.published_at).toISOString() : '';
                releases.push({tag_name: tag, name: String(release.name || tag).slice(0, 120), prerelease: release.prerelease === true, published_at: published, body: String(release.body || '').slice(0, 16000)});
            }
            if (batch.length < 100) return releases;
        }
    }

    async function fetchStableManifest(releaseTag = '') {
        const releases = await fetchPublishedReleases();
        const selected = sanitizeRef(releaseTag);
        const candidates = selected ? releases.filter(release => release.tag_name === selected) : stableReleaseCandidates(releases);
        if (selected && !candidates.length) {
            const error = new Error(tr('releaseNotFound', {release: selected}));
            error.releases = releases;
            throw error;
        }
        for (const release of candidates) {
            const tag = sanitizeRef(release.tag_name);
            const ref = `refs/tags/${tag}`;
            try {
                const manifest = sanitizeManifest(await fetchJson(rawUrl(ref, MANIFEST_FILE)));
                return {
                    manifest,
                    ref,
                    label: String(release.name || release.tag_name || 'Stable'),
                    origin: 'github', releases
                };
            } catch (cause) {
                if (!/HTTP 404/.test(cause?.message || '') && cause?.name !== 'SyntaxError') throw cause;
                if (selected) {
                    const error = new Error(tr('manifestMissingRelease', {release: selected, file: MANIFEST_FILE}));
                    error.releases = releases;
                    throw error;
                }
                // Stable releases that predate Lightflow Hub (or are unrelated)
                // are intentionally skipped instead of making the channel unusable.
            }
        }
        const error = new Error(tr('releaseUnavailable'));
        error.releases = releases;
        throw error;
    }

    async function fetchGitHubManifest(channel, experimentalBranch, releaseTag) {
        if (channel === 'stable') return fetchStableManifest(releaseTag);

        let ref = 'refs/heads/main';
        let label = 'main';
        if (channel === 'experimental') {
            const branch = sanitizeRef(experimentalBranch) || 'experimental';
            ref = `refs/heads/${branch}`;
            label = branch;
        }
        let manifest;
        try {
            manifest = sanitizeManifest(await fetchJson(rawUrl(ref, MANIFEST_FILE)));
        } catch (error) {
            if (/HTTP 404/.test(error?.message || '')) throw new Error(tr('manifestMissingBranch', {branch: label, file: MANIFEST_FILE}));
            throw error;
        }
        return {manifest, ref, label, origin: 'github'};
    }

    function desktopModules() {
        if (typeof require !== 'function') return null;
        try { return {fs: require('fs'), path: require('path')}; } catch (_) { return null; }
    }

    function inferSiblingDirectory() {
        const modules = desktopModules();
        const plugin = getPlugin(HUB_ID);
        if (!modules || !plugin?.path || /^https:/i.test(plugin.path)) return '';
        try { return modules.path.dirname(plugin.path); } catch (_) { return ''; }
    }

    function extractPluginVersion(source, module) {
        // Embedded artwork must not consume the registration metadata search window.
        const metadata = String(source || '').replace(/(['"])data:image\/[^'"]+\1/g, '""');
        const patterns = [
            /const\s+(?:PLUGIN_VERSION|VERSION|LAB_VERSION|HUB_VERSION)\s*=\s*['"]([^'"]+)['"]/,
            /(?:root\.)?Plugin\.register\([\s\S]{0,900}?version\s*:\s*['"]([^'"]+)['"]/,
            /version\s*:\s*['"]([^'"]+)['"]/
        ];
        for (const pattern of patterns) {
            const match = metadata.match(pattern);
            if (match) return match[1];
        }
        return module.version;
    }

    function readLocalManifest(directory) {
        const modules = desktopModules();
        if (!modules || !directory) throw new Error(tr('noFolder'));
        const manifestPath = modules.path.join(directory, MANIFEST_FILE);
        let manifest = makeEmbeddedManifest();
        if (modules.fs.existsSync(manifestPath)) manifest = sanitizeManifest(JSON.parse(modules.fs.readFileSync(manifestPath, 'utf8')));
        manifest.modules = manifest.modules.map(module => {
            const filePath = modules.path.join(directory, ...module.file.split('/'));
            const exists = modules.fs.existsSync(filePath) && modules.fs.statSync(filePath).isFile();
            let version = module.version;
            if (exists) version = extractPluginVersion(modules.fs.readFileSync(filePath, 'utf8'), module);
            return {...module, localPath: filePath, localExists: exists, version};
        });
        const hubPath = modules.path.join(directory, manifest.hub.file);
        manifest.hub.localPath = hubPath;
        manifest.hub.localExists = modules.fs.existsSync(hubPath) && modules.fs.statSync(hubPath).isFile();
        if (manifest.hub.localExists) manifest.hub.version = extractPluginVersion(modules.fs.readFileSync(hubPath, 'utf8'), manifest.hub);
        return {manifest, ref: directory, label: modules.path.basename(directory), origin: 'local'};
    }

    function getPlugin(id) {
        return globalThis.Plugins?.all?.find(plugin => plugin?.id === id && plugin.installed)
            || globalThis.Plugins?.registered?.[id]
            || null;
    }

    function getInstallation(id) {
        return globalThis.Plugins?.installed?.find(entry => entry?.id === id) || null;
    }

    function isManagedGitHubPath(path) {
        return typeof path === 'string' && path.startsWith(`https://raw.githubusercontent.com/${REPOSITORY.owner}/${REPOSITORY.name}/`);
    }

    function isCompatible(module) {
        if (module.variant === 'desktop' && (globalThis.isApp === false || globalThis.Blockbench?.isWeb === true)) return false;
        if (!globalThis.Blockbench?.version || typeof Blockbench.isOlderThan !== 'function') return true;
        return !Blockbench.isOlderThan(module.min_blockbench || '4.9.0');
    }

    function sourceKind(plugin, installation) {
        const source = plugin?.source || installation?.source || '';
        const path = plugin?.path || installation?.path || '';
        if (source === 'file') return 'local';
        if (source === 'url' && isManagedGitHubPath(path)) return 'github';
        return source ? 'other' : 'none';
    }

    function moduleView(module, preferences) {
        const plugin = getPlugin(module.id);
        const installation = getInstallation(module.id);
        const installed = !!(plugin?.installed || installation);
        const installedVersion = String(plugin?.version || installation?.version || '');
        const disabled = !!(plugin?.disabled || installation?.disabled);
        const source = sourceKind(plugin, installation);
        const installedPath = String(plugin?.path || installation?.path || '');
        const compatible = isCompatible(module);
        const updateAvailable = !module.unavailableInSource && installed && compatible && compareVersions(module.version, installedVersion) > 0;
        const expectedSource = preferences.source;
        let sourceMismatch = installed && source !== expectedSource;
        if (installed && !sourceMismatch && expectedSource === 'github') {
            try { sourceMismatch = installedPath !== rawUrl(currentRef, module.file); } catch (_) { sourceMismatch = true; }
        } else if (installed && !sourceMismatch && expectedSource === 'local' && module.localPath) {
            sourceMismatch = installedPath.replace(/\\/g, '/').toLowerCase() !== String(module.localPath).replace(/\\/g, '/').toLowerCase();
        }
        if (module.unavailableInSource) sourceMismatch = false;
        return {...module, plugin, installation, installed, installedVersion, disabled, source, compatible, updateAvailable, sourceMismatch};
    }

    function catalogModules() {
        // Keep newer installed tools visible while browsing an older release;
        // absent files must never become installation targets for that release.
        const ids = new Set(manifestState.modules.map(module => module.id));
        const extras = FALLBACK_MODULES.filter(module => !ids.has(module.id) && (getPlugin(module.id)?.installed || getInstallation(module.id)))
            .map(module => ({...module, description: language() === 'es' ? module.description_es : module.description, unavailableInSource: true}));
        return [...manifestState.modules, ...extras];
    }

    function dependencyOrder(modules, requestedIds) {
        const byId = new Map(modules.map(module => [module.id, module]));
        const result = [];
        const visiting = new Set();
        const visited = new Set();
        function visit(id) {
            if (visited.has(id)) return;
            if (visiting.has(id)) throw new Error(`Circular dependency: ${id}`);
            const module = byId.get(id);
            if (!module) throw new Error(`Missing dependency: ${id}`);
            visiting.add(id);
            module.dependencies.forEach(visit);
            visiting.delete(id);
            visited.add(id);
            result.push(module);
        }
        requestedIds.forEach(visit);
        return result;
    }

    function confirmBox(message, confirmLabel) {
        return new Promise(resolve => {
            Blockbench.showMessageBox({
                title: tr('title'), message, icon: 'extension',
                buttons: [confirmLabel || 'dialog.continue', 'dialog.cancel'], confirm: 0, cancel: 1
            }, result => resolve(result === 0));
        });
    }

    function resetPluginMetadata(plugin) {
        ['tags', 'contributors', 'dependencies'].forEach(key => {
            if (Array.isArray(plugin?.[key])) plugin[key].length = 0;
        });
        if (plugin) {
            plugin.details = null;
            plugin.about_fetched = false;
            plugin.changelog_fetched = false;
        }
    }


    function verifyLoaded(plugin, module, path) {
        if (!plugin.installed || getPlugin(module.id) !== plugin || plugin.path !== path
            || compareVersions(plugin.version, module.version) !== 0) {
            throw new Error(tr('loadFailed', {name: module.title}));
        }
    }

    function unloadForReplacement(plugin) {
        // Published Shader Architect builds use Menu.menus in their synchronous
        // unload callback. Blockbench 5.2 exposes those menus on element prototypes.
        // Bridge the old callback before loading new code; never skip its cleanup.
        if (plugin.id !== 'shader_architect' || typeof Menu === 'undefined' || Menu.menus
            || !/\bMenu\.menus\b/.test(String(plugin.onunload || ''))) return plugin.unload?.();
        const descriptor = Object.getOwnPropertyDescriptor(Menu, 'menus');
        if (descriptor && !descriptor.configurable) return plugin.unload?.();
        const menus = Object.create(null);
        const types = [
            ['outliner_cube', typeof Cube === 'undefined' ? null : Cube],
            ['outliner_mesh', typeof Mesh === 'undefined' ? null : Mesh],
            ['outliner_texture_mesh', typeof TextureMesh === 'undefined' ? null : TextureMesh]
        ];
        for (const [id, type] of types) {
            const menu = type?.prototype?.menu;
            if (Array.isArray(menu?.structure)) menus[id] = menu;
        }
        // These two actions were not tracked by the published unload callback.
        // Capture their identities before cleanup; never delete a replacement.
        const actions = ['sa_apply_override', 'sa_clear_override']
            .map(id => globalThis.BarItems?.[id])
            .filter(action => action && Object.values(menus).some(menu => menu.structure.includes(action)));
        Object.defineProperty(Menu, 'menus', {value: menus, configurable: true});
        try {
            const result = plugin.unload?.();
            for (const action of actions) {
                if (globalThis.BarItems?.[action.id] === action) action.delete?.();
            }
            return result;
        }
        finally {
            if (descriptor) Object.defineProperty(Menu, 'menus', descriptor);
            else delete Menu.menus;
        }
    }

    async function replacePlugin(module, kind, path, options = {}) {
        assertPluginSourceFilename(module.id, path);
        if (!options.preflighted) {
            if (kind === 'github') await probeRemotePlugin(path, module.id);
            else {
                const desktop = desktopModules();
                if (!desktop || !desktop.fs.existsSync(path)) throw new Error(`${tr('missingLocal')}: ${module.file}`);
                validatePluginSource(desktop.fs.readFileSync(path, 'utf8'), module.id);
            }
        }
        if (disposed) return false;
        let plugin = getPlugin(module.id);
        const previous = plugin?.installed ? {path: plugin.path, source: plugin.source, version: plugin.version, disabled: plugin.disabled} : null;
        if (previous && sourceKind(plugin, getInstallation(module.id)) !== kind && !options.sourceApproved) {
            if (!await confirmBox(tr('confirmReplace', {name: module.title, source: kind === 'local' ? tr('local') : 'GitHub'}), tr('replace'))) return false;
        }
        if (disposed) return false;
        // Reuse native records across source changes. Uninstall callbacks can erase
        // artist preferences and project data, so they are reserved for Uninstall.
        if (!plugin) plugin = new Plugin(module.id, {disabled: previous?.disabled});
        try {
            if (previous && !plugin.disabled) unloadForReplacement(plugin);
            // Native Plugin.reload increments this before loading a local file.
            // Reusing the same path/version without it can evaluate cached code,
            // even though preflight just read the updated source from disk.
            if (previous) plugin.cache_version = (Number(plugin.cache_version) || 0) + 1;
            resetPluginMetadata(plugin);
            plugin.version = '';
            plugin.installed = false;
            plugin.disabled = !!previous?.disabled;
            if (kind === 'local') await plugin.loadFromFile({path, name: module.file.split('/').pop(), content: ''}, false);
            else await plugin.loadFromURL(path, false);
            verifyLoaded(plugin, module, path);
            return true;
        } catch (error) {
            // Native loaders may resolve despite a failed download/evaluation.
            // Reload the previous source and check its version before reporting recovery.
            if (previous) {
                try {
                    if (!plugin.disabled) unloadForReplacement(plugin);
                    plugin.cache_version = (Number(plugin.cache_version) || 0) + 1;
                    resetPluginMetadata(plugin); plugin.version = ''; plugin.installed = false;
                    plugin.disabled = !!previous.disabled;
                    if (previous.source === 'file') await plugin.loadFromFile({path: previous.path, name: String(previous.path).replace(/\\/g, '/').split('/').pop(), content: ''}, false);
                    else if (previous.source === 'url') await plugin.loadFromURL(previous.path, false);
                    else if (typeof plugin.load === 'function') { plugin.source = previous.source; await plugin.load(); }
                    verifyLoaded(plugin, {...module, version: previous.version}, previous.path);
                    error.message += ` ${tr('restored')}`;
                } catch (_) { error.message += ` ${tr('restoreFailed')}`; }
            } else {
                plugin.uninstall?.();
            }
            throw error;
        }
    }

    function replaceWithUrl(module, url, options) { return replacePlugin(module, 'github', url, options); }
    function replaceWithFile(module, path, options) { return replacePlugin(module, 'local', path, options); }

    function moduleSource(module, preferences) {
        if (preferences.source === 'local') {
            if (!module.localPath || !module.localExists) throw new Error(`${tr('missingLocal')}: ${module.file}`);
            return {kind: 'local', value: assertPluginSourceFilename(module.id, module.localPath)};
        }
        return {kind: 'github', value: assertPluginSourceFilename(module.id, rawUrl(currentRef, module.file))};
    }

    function needsPluginWrite(view, requestedIds, force) {
        return !view.installed || view.updateAvailable || view.sourceMismatch || (force && requestedIds.includes(view.id));
    }

    async function installModules(requestedIds, preferences, options = {}) {
        const snapshot = {...preferences};
        const activateDependencies = requestedIds.some(id => !getPlugin(id)?.disabled);
        const plan = dependencyOrder(manifestState.modules, requestedIds).map(module => {
            if (!isCompatible(module)) throw new Error(`${module.title}: ${tr('incompatible')} (Blockbench ${module.min_blockbench}+)`);
            const view = moduleView(module, snapshot);
            return {module, view, source: moduleSource(module, snapshot), needsWrite: needsPluginWrite(view, requestedIds, options.force)};
        });
        const writes = plan.filter(item => item.needsWrite);
        // Verify the entire batch before unloading any installed tool.
        for (let index = 0; index < writes.length; index++) {
            if (disposed) return;
            const {module, source} = writes[index];
            options.progress?.({phase: 'preparing', name: module.title, current: index + 1, total: writes.length});
            try {
                if (source.kind === 'github') await probeRemotePlugin(source.value, module.id);
                else validatePluginSource(desktopModules().fs.readFileSync(source.value, 'utf8'), module.id);
            } catch (cause) {
                throw new Error(`${module.title}: ${cause.message}`, {cause});
            }
        }
        let completed = 0;
        for (const {module, source, needsWrite} of plan) {
            if (disposed) return;
            if (needsWrite) {
                options.progress?.({phase: 'installing', name: module.title, current: completed + 1, total: writes.length});
                const accepted = await replacePlugin(module, source.kind, source.value, {...options, preflighted: true});
                if (!accepted) return;
                completed++;
            }
            const plugin = getPlugin(module.id);
            if (plugin?.disabled && (options.activate || (!requestedIds.includes(module.id) && activateDependencies))) plugin.toggleDisabled();
        }
        return {completed};
    }

    function queueOperation(work) {
        const next = operationLock.then(work, work);
        operationLock = next.catch(() => {});
        return next;
    }

    function openUrl(url) {
        if (globalThis.Blockbench?.openLink) Blockbench.openLink(url);
        else if (typeof window !== 'undefined') window.open(url, '_blank', 'noopener');
    }

    function renderReleaseMarkdown(text, title = '') {
        const source = String(text || '');
        const escaped = () => `<p>${source.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>')}</p>`;
        // Use Blockbench's bundled parser and sanitizer, without adding a network dependency.
        if (typeof marked === 'undefined' || typeof DOMPurify === 'undefined' || typeof DOMParser === 'undefined') return escaped();
        try {
            const html = typeof marked.parse === 'function' ? marked.parse(source, {gfm:true, breaks:false}) : marked(source);
            const clean = DOMPurify.sanitize(html, {
                ALLOWED_TAGS: ['p','br','hr','h1','h2','h3','h4','h5','h6','strong','em','del','s','blockquote','ul','ol','li','pre','code','a','img','table','thead','tbody','tr','th','td','details','summary'],
                ALLOWED_ATTR: ['href','title','src','alt','start'], ALLOW_DATA_ATTR:false, ALLOW_ARIA_ATTR:false
            });
            const document = new DOMParser().parseFromString(clean, 'text/html');
            document.querySelectorAll('a').forEach(link => {
                const href = link.getAttribute('href') || '';
                if (!/^https?:\/\//i.test(href)) link.removeAttribute('href');
                else { link.setAttribute('target', '_blank'); link.setAttribute('rel', 'noopener noreferrer'); }
            });
            document.querySelectorAll('img').forEach(image => {
                if (!/^https:\/\//i.test(image.getAttribute('src') || '')) image.remove();
                else { image.loading = 'lazy'; image.decoding = 'async'; image.referrerPolicy = 'no-referrer'; }
            });
            const first = document.body.firstElementChild;
            const normalize = value => value.replace(/\s+/g, ' ').trim().toLowerCase();
            if (first?.tagName === 'H1' && title && normalize(first.textContent) === normalize(title)) first.remove();
            return document.body.innerHTML;
        } catch (_) { return escaped(); }
    }

    function installedDependents(id) {
        return catalogModules().filter(module => module.dependencies.includes(id) && !!getInstallation(module.id));
    }

    function statusText(view) {
        if (!view.compatible) return tr('incompatible');
        if (!view.installed) return tr('available');
        if (view.disabled) return tr('disabled');
        if (view.updateAvailable) return tr('update');
        return tr('installed');
    }

    function statusClass(view) {
        if (!view.compatible) return 'incompatible';
        if (!view.installed) return 'available';
        if (view.disabled) return 'disabled';
        if (view.updateAvailable) return 'update';
        return 'installed';
    }

    function sourceText(view) {
        if (view.source === 'github') return tr('sourceGithub');
        if (view.source === 'local') return tr('sourceLocal');
        return tr('sourceOther');
    }

    async function loadManifestForPreferences(preferences, allowFallback = true) {
        if (preferences.source === 'local') {
            const directory = preferences.localDirectory || inferSiblingDirectory();
            if (!directory) throw new Error(tr('noFolder'));
            preferences.localDirectory = directory;
            savePreferences(preferences);
            return readLocalManifest(directory);
        }
        try {
            const result = await fetchGitHubManifest(preferences.channel, preferences.experimentalBranch, preferences.releaseTag);
            try { localStorage.setItem(CACHE_KEY, JSON.stringify({time: Date.now(), channel: preferences.channel, branch: preferences.experimentalBranch, releaseTag: sanitizeRef(preferences.releaseTag), result})); } catch (_) { /* Catalog still works for this session. */ }
            return result;
        } catch (error) {
            const cached = readJsonStorage(CACHE_KEY, null);
            if (cached?.result?.manifest && cached.channel === preferences.channel && cached.branch === preferences.experimentalBranch
                && (preferences.channel !== 'stable' || sanitizeRef(cached.releaseTag) === sanitizeRef(preferences.releaseTag))
                && (!preferences.releaseTag || preferences.channel !== 'stable' || cached.result.ref === `refs/tags/${sanitizeRef(preferences.releaseTag)}`)
                && !Array.isArray(error.releases)) {
                return {...cached.result, manifest: sanitizeManifest(cached.result.manifest),
                    warning: tr(error.releaseListRateLimited ? 'rateLimitedCatalog' : 'offlineHint'), cached: true};
            }
            if (allowFallback && error.releaseListRateLimited && preferences.channel === 'stable' && !preferences.releaseTag) {
                const ref = `refs/tags/${STABLE_BOOTSTRAP_TAG}`;
                const manifest = sanitizeManifest(await fetchJson(rawUrl(ref, MANIFEST_FILE)));
                return {manifest, ref, label: STABLE_BOOTSTRAP_TAG, origin: 'github', warning: tr('rateLimitedCatalog'), cached: true};
            }
            if (!allowFallback || preferences.channel === 'stable') throw error;
            return {manifest: makeEmbeddedManifest(), ref: `refs/heads/${preferences.channel === 'experimental' ? preferences.experimentalBranch : 'main'}`, label: preferences.channel, origin: 'embedded', warning: tr('manifestFallback')};
        }
    }

    function applyManifestResult(result) {
        manifestState = result.manifest;
        currentRef = result.ref;
        manifestOrigin = result.origin;
        return result;
    }

    function notifyError(error) {
        console.error('[Lightflow Hub]', error);
        Blockbench.showMessageBox({title: tr('title'), message: error?.message || String(error), icon: 'error'});
    }

    function friendlyError(error) {
        const message = error?.message || String(error);
        if (error?.name === 'AbortError') return tr('timeoutError');
        if (/HTTP (403|429)/.test(message)) return tr('rateLimit');
        if (/failed to fetch|network|offline/i.test(message)) return tr('networkError');
        return message;
    }

